insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, ownership_disclosure, status, attributes) select 'the-keeper-league', 'The Keeper League', array['podcast','community']::listing_type[], 'The AFL Fantasy podcast for keeper and draft leagues.', 'An AFL Fantasy show that looks past the superstars to the prospects, role changes and waiver picks that matter in keeper and draft leagues. Runs a Discord and a paid membership.', 'https://keeperleaguepod.com.au', 'freemium'::pricing_model, 'Free show, with a paid membership', array['afl']::text[], null, null, 'draft'::publish_status, '{"starter": true, "vet_note": "Independent Australian show. No betting content expected. Add the RSS feed.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('The Keeper League')) on conflict (slug) do nothing;
