insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, ownership_disclosure, status, attributes) select 'r-sportsbook', 'r/sportsbook', array['community']::listing_type[], 'Reddit''s main sports betting forum.', 'A large betting community with daily discussion threads for each sport, strategy posts and a strict set of rules against selling picks.', 'https://www.reddit.com/r/sportsbook/', 'free'::pricing_model, null, array[]::text[], null, null, 'draft'::publish_status, '{"starter": true, "vet_note": "Public community with volunteer moderators, so there is no owner to contact. Read the current rules and pinned posts before publishing."}'::jsonb where not exists (select 1 from listings where lower(name) = lower('r/sportsbook')) on conflict (slug) do nothing;
